function faceSelectedSide(){viewer?.face(state.printSide);viewerPromise?.then(()=>viewer?.face(state.printSide))}
function setPrintSides(value){state.printSides=value==='both'?['front','back']:[value];if(!state.printSides.includes(state.printSide))activateSide(state.printSides[0]);state.qualityAccepted=false;state.qualityReview=false}
function removeSide(side){const previous=state.images[side];if(previous?.startsWith('blob:'))URL.revokeObjectURL(previous);state.images[side]='';state.files[side]='';state.assessments[side]=null;state.qualityAccepted=false;state.qualityReview=false;state.uploaded=hasRequiredFiles();activateSide(includedSides()[0]);removeSavedDesignFile(side).catch(()=>{})}
function artworkTone(image){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=48;
 const context=canvas.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,48,48);
 const pixels=context.getImageData(0,0,48,48).data;let visible=0,light=0,luminance=0;
 for(let index=0;index<pixels.length;index+=4){
  if(pixels[index+3]<48)continue;
  const value=.2126*pixels[index]+.7152*pixels[index+1]+.0722*pixels[index+2];visible++;luminance+=value;if(value>175)light++;
 }
 return visible&&((light/visible)>.22||luminance/visible>150)?'light':'dark';
}
function printSidesHtml(){
 const selected=hasTwoSides()?'both':state.printSide;
 return `<fieldset class="print-side-picker"><legend>¿Dónde va tu diseño?</legend><div class="print-choice-cards">${[['front','Solo frente','Incluido'],['back','Solo espalda','Incluido'],['both','Ambos',`+${money(PRINT_EXTRAS_CLP.both)}`]].map(([value,label,price])=>`<button type="button" data-print-sides="${value}" class="print-choice ${selected===value?'selected':''}" aria-pressed="${selected===value}"><strong>${label}</strong><span>${price}</span></button>`).join('')}</div></fieldset>`;
}
function uploadCardHtml(side){
 const image=state.images[side];const assessment=state.assessments[side];const checking=state.checking&&state.checkingSide===side;
 const readyLabel=side==='front'?'Frente listo':'Espalda lista';
 const action=checking?'Revisando archivo…':image?`${readyLabel} · Cambiar`:`Cargar ${side==='front'?'frente':'espalda'}`;
 const detail=checking?'Comprobando formato y resolución':image?(assessment?.qualifies?'Archivo cargado':'Archivo cargado · revisaremos su calidad'):'JPG, PNG o WEBP · máx. 50 MB';
 return `<div class="upload-card ${image?'uploaded':''}" data-upload-card="${side}"><label class="dropzone upload-zone" data-drop-side="${side}"><input id="file-${side}" data-file-side="${side}" type="file" accept="image/png,image/jpeg,image/webp"/><span>${image?'<img src="'+image+'" alt="Miniatura del diseño para '+sideNames[side].toLowerCase()+'">':'<svg class="upload-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V4m-5 5 5-5 5 5"/><path d="M5 14v5h14v-5"/></svg>'}</span><strong>${action}</strong><small>${detail}</small></label>${image?`<button type="button" class="small-button" data-remove-side="${side}">Quitar archivo</button>`:''}</div>`;
}
const escapeText=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatChilePhoneLocal=value=>{let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('569')&&digits.length>=11)digits=digits.slice(3);else if(digits.startsWith('56')&&digits.length>=10)digits=digits.slice(2).replace(/^9/,'');else if(digits.startsWith('9')&&digits.length===9)digits=digits.slice(1);else if(digits.length>8)digits=digits.slice(-8);return digits.slice(0,8).replace(/^(\d{4})(\d+)/,'$1 $2')};
const fullChilePhone=value=>{const local=formatChilePhoneLocal(value);return local?`+56 9 ${local}`:''};
const phoneFieldHtml=(id,value)=>`<div class="phone-input"><span class="phone-prefix" aria-hidden="true">🇨🇱 <b>+56 9</b></span><input id="${id}" type="tel" required autocomplete="tel" inputmode="numeric" pattern="[0-9]{4} [0-9]{4}" maxlength="9" placeholder="1234 5678" value="${escapeText(formatChilePhoneLocal(value))}"></div>`;
