function addReferenceFiles(fileList){
 const available=Math.max(0,6-state.references.length);const incoming=[...(fileList||[])];
 if(!available)return toast('Puedes adjuntar hasta 6 fotos de referencia.');
 const compatible=incoming.filter(file=>['image/png','image/jpeg','image/webp'].includes(file.type)&&file.size<=PRINT_POLICY.maxBytes).slice(0,available);
 compatible.forEach(file=>state.references.push({name:file.name,url:URL.createObjectURL(file)}));
 renderStep();
 if(!compatible.length)return toast('Elige fotos JPG, PNG o WEBP de hasta 50 MB.');
 if(compatible.length<incoming.length)toast(`Adjuntamos ${compatible.length} foto${compatible.length===1?'':'s'}. Algunas no eran compatibles o superaban el límite.`);
 else toast(`${compatible.length} foto${compatible.length===1?' adjunta':'s adjuntas'} como referencia opcional.`);
}
async function upload(file,side=state.printSide){
 if(!file)return;
 if(!['image/png','image/jpeg','image/webp'].includes(file.type))return toast('Formato no compatible. Elige JPG, PNG o WEBP.');
 if(file.size>PRINT_POLICY.maxBytes)return toast('El archivo supera los 50 MB. Reduce su peso y vuelve a subirlo.');
 const token=++uploadVersions[side],url=URL.createObjectURL(file);state.checking=true;state.checkingSide=side;activateSide(side);renderStep();viewer?.face(side);
 try{
  const img=new Image();img.src=url;await img.decode();if(token!==uploadVersions[side]){URL.revokeObjectURL(url);return}
  const previous=state.images[side];if(previous?.startsWith('blob:'))URL.revokeObjectURL(previous);
  state.images[side]=url;state.files[side]=file.name;activateSide(side);state.uploaded=hasRequiredFiles();state.file=file.name;state.artworkTone=artworkTone(img);state.assessment=checkResolution(img.naturalWidth,img.naturalHeight);state.assessments[side]=state.assessment;state.checking=false;state.checkingSide='';state.qualityAccepted=false;state.qualityReview=false;saveDesignFile(side,file).catch(()=>toast('El diseño se cargó, pero este navegador no pudo guardarlo para después.'));renderStep();faceSelectedSide();if(!state.assessment.qualifies)toast('Archivo cargado. Te explicaremos la revisión antes de avanzar.')
 }catch{URL.revokeObjectURL(url);if(token===uploadVersions[side]){state.checking=false;state.checkingSide='';renderStep();toast('El archivo no se pudo leer. Prueba con otra imagen.')}}}
async function restoreSavedDesigns(){try{const saved=await savedDesignFiles();for(const item of saved){if(item.expiresAt<=Date.now()){removeSavedDesignFile(item.side).catch(()=>{});continue}if(!['front','back'].includes(item.side)||!(item.file instanceof Blob))continue;const url=URL.createObjectURL(item.file);const image=new Image();image.src=url;try{await image.decode()}catch{URL.revokeObjectURL(url);removeSavedDesignFile(item.side).catch(()=>{});continue}state.images[item.side]=url;state.files[item.side]=item.file.name||'Diseño guardado';state.assessments[item.side]=checkResolution(image.naturalWidth,image.naturalHeight);state.artworkTone=artworkTone(image)}state.uploaded=hasRequiredFiles();activateSide(includedSides()[0]);syncPreview();if(studio.open)renderStep()}catch{}}
function persistDraft(){syncFullName();try{saveForFifteenDays(DRAFT_KEY,{kind:state.kind,size:state.size,color:state.color,printSides:state.printSides,qualityReview:state.qualityReview,fulfillment:state.fulfillment,date:new Date().toISOString()})}catch{toast('No pudimos guardar el avance en este navegador.')}}
document.querySelector('#back').onclick=()=>{state.step=state.step===4&&!failingSides().length?2:Math.max(1,state.step-1);renderStep()};
document.querySelector('#design-form').onsubmit=e=>{
 e.preventDefault();if(state.checking)return;
 if(state.step===1){const email=document.querySelector('#customer-email');if(!email?.checkValidity())return email?.reportValidity();state.email=email.value.trim();storeCustomerDetails();state.step=2;return renderStep()}
 if(state.step===2){const firstName=document.querySelector('#customer-first-name'),lastName=document.querySelector('#customer-last-name'),phone=document.querySelector('#customer-phone');if(!firstName?.checkValidity())return firstName?.reportValidity();if(!lastName?.checkValidity())return lastName?.reportValidity();if(!phone?.checkValidity())return phone?.reportValidity();state.firstName=firstName.value.trim();state.lastName=lastName.value.trim();state.phone=fullChilePhone(phone.value);storeCustomerDetails();if(!hasRequiredFiles()){const missing=includedSides().filter(side=>!state.images[side]).map(side=>sideNames[side].toLowerCase()).join(' y ');return toast(`Carga el archivo de ${missing} para continuar.`)}state.step=failingSides().length?3:4;activateSide(includedSides()[0]);return renderStep()}
 if(state.step===3){state.qualityAccepted=true;state.qualityReview=true;state.step=4;return renderStep()}
 if(state.step===4){const summaryFirstName=document.querySelector('#summary-first-name'),summaryLastName=document.querySelector('#summary-last-name'),summaryEmail=document.querySelector('#summary-email'),summaryPhone=document.querySelector('#summary-phone');if(state.editingContact){for(const field of [summaryFirstName,summaryLastName,summaryEmail,summaryPhone])if(!field?.checkValidity())return field?.reportValidity();state.firstName=summaryFirstName.value.trim();state.lastName=summaryLastName.value.trim();state.email=summaryEmail.value.trim();state.phone=fullChilePhone(summaryPhone.value)}if(state.fulfillment==='delivery'){const fields=['delivery-region','delivery-address','delivery-commune'].map(id=>document.querySelector(`#${id}`));for(const field of fields)if(!field?.checkValidity())return field?.reportValidity();const matchedRegion=chileRegions.find(region=>samePlace(region,fields[0].value.trim()));if(!matchedRegion){fields[0].setCustomValidity('Selecciona una región de la lista.');return fields[0].reportValidity()}const matchedCommune=communesForRegion(matchedRegion).find(commune=>samePlace(commune,fields[2].value.trim()));if(!matchedCommune){fields[2].setCustomValidity('Selecciona una comuna de la lista.');return fields[2].reportValidity()}state.region=matchedRegion;state.address=fields[1].value.trim();state.commune=matchedCommune;state.addressExtra=document.querySelector('#delivery-address-extra')?.value.trim()||'';state.deliveryNotes=document.querySelector('#delivery-notes')?.value.trim()||''}storeCustomerDetails();persistDraft();state.editingContact=false;state.step=5;return renderStep()}
 const checkoutEmail=document.querySelector('#checkout-email');if(!checkoutEmail?.checkValidity())return checkoutEmail?.reportValidity();state.email=checkoutEmail.value.trim();storeCustomerDetails();state.checkoutReady=true;persistDraft();toast('Checkout de demostración listo. No se realizó ningún cobro.')
};
